class Solution:
    def countBits(self, n: int) -> List[int]:
        ans = [0] * (n + 1)                     # ans[0] = 0
        for i in range(1, n + 1):
            ans[i] = ans[i >> 1] + (i & 1)      # 去掉最低位的数已经算过了，再加上最低位
        return ans

