class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];             // ans[0] = 0
        for (int i = 1; i <= n; i++) {
            ans[i] = ans[i >> 1] + (i & 1);     // 去掉最低位的数已经算过了，再加上最低位
        }
        return ans;
    }
}

